"""Publish the 17 October follow-up from inspected primary text and qualified reporting."""
from pathlib import Path
import json,re,html
R=Path(__file__).resolve().parents[1];D=json.loads((R/'assets/research-data.json').read_text())
def link(s,label):return '<a class="citation" href="../evidence/#'+s+'">'+label+'</a>'
def write(slug,title,deck,body):
 p=R/slug/'index.html';p.parent.mkdir(exist_ok=True)
 t=p.read_text() if p.exists() else (R/'research/index.html').read_text()
 main=f'<main id="main" class="container"><div class="article-top"><span class="eyebrow">RESEARCH NOTE / 17 OCTOBER 2026</span><h1>{title}</h1><p class="lede">{deck}</p></div><article class="prose research-prose">{body}</article></main>'
 t=re.sub(r'<main .*?</main>',lambda _:main,t,flags=re.S)
 t=re.sub(r'<title>.*?</title>','<title>'+html.escape(title)+' | The SIR Files</title>',t)
 t=re.sub(r'<meta name="description" content="[^"]*">','<meta name="description" content="'+html.escape(deck,quote=True)+'">',t)
 p.write_text(t)
write('delhi-form-6-order','Returning to the roll: what the Delhi order decides.','A four-page court order answers a question for two applicants. It does not establish their eventual inclusion or settle the wider Form 6 dispute.',
 '<h2 id="decision">The decision, in context</h2><p>In Nilotpal Datta &amp; Anr. v. ECI, W.P.(C) 14955/2026, the Delhi High Court closed proceedings on 14 October. Paragraph 7 permits the petitioners to file Form 6 for processing under law. Paragraph 6 rejects the first petitioner’s concern about a false-declaration accusation in light of the ECI counsel’s position, given on the ERO’s instructions. '+link('DHC-FORM6-OCT14','Order, paragraphs 6–7')+'</p>'
 '<h2 id="limits">What this leaves open</h2><p>The order does not record completed inclusion. It does not supply a revised form or decide every issue raised about the declaration. Our reading is therefore narrow: an application route is recorded, while the result still needs evidence.</p>'
 '<h2 id="outcomes">Follow the application through</h2><p>For an outcome audit, we would need the receipt, the ERO’s decision and the corresponding entry in a published roll or supplement. A statement about the availability of a form cannot replace those records.</p>'
 '<h2 id="drive">A separate administrative development</h2><p>The Indian Express reports a Delhi re-verification drive covering roughly 47.5 lakh draft omissions. This is reported activity. We have not inspected the signed local instruction or matched restoration results. '+link('IE-DELHI-RECHECK-OCT17','17 October report')+'</p>'
 '<h2 id="provenance">How we checked the document</h2><p>We read the four-page publisher-hosted PDF and inspected pages 3–4 visually. A second publisher supplied identical bytes. That is a copy check, not independent corroboration. Court-portal and cryptographic-signature verification remain outstanding. The source ledger preserves the file fingerprint.</p>'
 '<p><a href="../form-6/">Compare the Form 6 versions</a> · <a href="../state-files/delhi/">Read the Delhi file</a></p>')
write('statutory-source-update','A newer Act compilation. A clearer version boundary.','The ECI’s July 2025 compilation fills a source gap. It does not certify every legal change through October 2026.',
 '<h2 id="baseline">A better starting point</h2><p>The ECI publishes a 33-page Representation of the People Act, 1950 compilation labelled 22 July 2025. Its amendment list includes Act 49 of 2021. Section 14(b) includes four qualifying dates. Sections 23(4)–(6) include the Aadhaar-related provisions. '+link('RPA-ECI-2025','ECI compilation')+'</p>'
 '<h2 id="version">Why the date matters</h2><p>Our earlier linked compilation omitted later amendments and remains labelled historical. Finding a newer file improves the baseline; it does not establish that nothing changed after its stated date. Full currency requires checking later Acts, commencement notifications and the applicable rule versions.</p>'
 '<h2 id="declaration">Read the declaration issue precisely</h2><p>Section 31 concerns a written false statement with the specified knowledge or belief. It is not a rule that every returning applicant automatically commits an offence. Nor does this source settle the wording or operation of a later online form. Those are different evidence questions. '+link('RPA-ECI-2025','Section 31, printed page 23')+'</p>'
 '<h2 id="access">What we verified</h2><p>The indexed PDF text was inspected. Direct byte retrieval returned HTTP 406, so no local file hash or complete visual inspection is claimed. This finding partly fills the statutory-source gap. It does not close it.</p><p><a href="../investigations/#G09">See the remaining legal-source checks</a></p>')
# Make the review landing page reflect this edition while retaining links to earlier work.
write('research','The latest research.','17 October 2026. New primary text, clearer limits and the next records to obtain.',
 '<h2 id="latest">What changed in this review</h2><div class="review-links"><a href="../delhi-form-6-order/"><span class="eyebrow">COURT ORDER</span><h3>Returning to the roll: what the Delhi order decides.</h3><p>The 14 October order copy is now inspected. Applications and completed inclusion stay separate.</p></a><a href="../statutory-source-update/"><span class="eyebrow">SOURCE UPDATE</span><h3>A newer Act compilation.</h3><p>A July 2025 official text fills part of the version gap.</p></a></div>'
 '<h2 id="still-open">What remains open</h2><p>The exact challenged online Form 6, the signed Supreme Court October record, Delhi’s local re-verification instruction, person-linked outcomes and post-July 2025 statutory changes still need evidence.</p>'
 '<h2 id="previous">Earlier research</h2><ul><li><a href="../audit/">Full audit and 36-jurisdiction coverage matrix</a></li><li><a href="../restoration-and-ssr/">The special drive and the next summary revision</a></li><li><a href="../maharashtra-primary-records/">Maharashtra’s signed extension and application counts</a></li><li><a href="../form-7/">Form 7 limits and scrutiny safeguards</a></li><li><a href="../ecinet/">ECINet: an announced review is not a published audit</a></li></ul>'
 f'<div class="insight">This edition tracks {len(D["sources"])} source records and {len(D["claims"])} claims across 36 jurisdiction files. Mirrors are not independent documents. Eight files have developed analysis; 28 remain reference files.</div>')
# Keep earlier analyses accurate without concealing their original review limitations.
p=R/'form-6/index.html';t=p.read_text();banner='<div class="followup-note"><strong>17 October update.</strong> A Delhi High Court order copy is now inspected. The broader Supreme Court question remains separate. <a href="../delhi-form-6-order/">Read the order analysis →</a></div>'
t=t.replace('<article class="prose research-prose">','<article class="prose research-prose">'+banner,1)
t=t.replace('The linked Act compilation lacks later amendments. Its upload path does not establish currency. A current consolidation and commencement chain are still required before relying on changed provisions.','The earlier linked Act compilation lacks later amendments. A newer ECI text dated July 2025 is now located. Later amendments, commencement instruments and rule versions remain to be checked. <a href="../statutory-source-update/">Read the statutory-source update.</a>')
p.write_text(t)
p=R/'legal/index.html';t=p.read_text();t=t.replace('Version warning: the linked Act compilation is historical and omits later amendments. Current consolidation remains open.','Version update: the earlier Act compilation is historical. A newer July 2025 ECI text is now located; full current-law consolidation remains open. <a href="../statutory-source-update/">Read the source comparison.</a>');p.write_text(t)
p=R/'audit/index.html';t=p.read_text().replace('Current consolidated statutory text and the actual Maharashtra Gazette issue remain open.','A July 2025 ECI statutory compilation has now been located, but later changes and rule versions remain open. The actual Maharashtra Gazette issue is also unverified.');p.write_text(t)
print('Rendered follow-up articles and review page')
